mapper.select:
/* TodoRepository.findById */
SELECT todo_id,
       user_id,
       todo_title,
       finished,
       created_at
FROM todo
WHERE todo_id = #{todoId}
  AND user_id = #{userId}

/* TodoRepository.countByFinished */
SELECT COUNT(todo_id)
FROM todo
WHERE user_id = #{userId}
  AND finished = #{finished}

mapper.update:
/* TodoRepository.update */
UPDATE todo
SET todo_title = #{todoTitle},
    finished   = #{finished},
    created_at = #{createdAt}
WHERE todo_id = #{todoId}
  AND user_id = #{userId}

/* TodoRepository.updateFinishedById */
UPDATE todo
SET finished = true
WHERE todo_id = #{todoId}
  AND user_id = #{userId}

mapper.delete:
/* TodoRepository.delete */
DELETE
FROM todo
WHERE todo_id = #{todoId}
  AND user_id = #{userId}

/* TodoRepository.deleteById */
DELETE
FROM todo
WHERE todo_id = #{todoId}
  AND user_id = #{userId}
